134	        RollupService.Snapshot before = rollup.snapshot(sheetId);
135	        String tail = "";
136	        // settling is the step from OPEN; a pending claim is settled by approving it
137	        if (!claim.getStatus().canMoveTo(next) || next == ClaimStatus.PENDING
138	                || (next == ClaimStatus.SETTLED && claim.getStatus() != ClaimStatus.OPEN)
139	                || (next == ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.DRAFT)) {
140	            throw new ResponseStatusException(HttpStatus.CONFLICT,
141	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
142	        }
143	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.load(sheetId).getToday())) {
144	            throw new ResponseStatusException(HttpStatus.CONFLICT,
145	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
146	        }
147	        if (next == ClaimStatus.SETTLED && by.equals(claim.getOpenedBy())) {
148	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The user who opened a claim cannot settle it.");
149	        }
150	        if (next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
151	            refuseVoidOfSettled(by, sheetId, claim);
152	            // the frozen figure leaves every total; the claim keeps its number and shows the figure it had
153	            tail = " reversed=" + text(claim.getSettledDue());
154	        }
155	        if (next == ClaimStatus.OPEN) {
156	            number(sheetId, claim);
157	            claim.setOpenedBy(by);
158	        }
159	        Person person = person(sheetId, claim.getPersonId());
160	        String event = switch (next) {
161	            case OPEN -> "CLAIM_OPENED";
162	            case SETTLED -> "CLAIM_SETTLED";
163	            case VOID -> "CLAIM_VOIDED";
164	            case DRAFT, PENDING -> throw new IllegalStateException();
165	        };
166	        if (next == ClaimStatus.SETTLED) {
167	            // the due is fixed at the figure a statement bound it to, else at the rate the person's grade has in
168	            // force on the claim's date, with the late charge it has gained by today, and at least the floor in force
169	            // on its date; with none it stays live
170	            BigDecimal figure = claim.isStated() && claim.getStatedDue() != null ? claim.getStatedDue()
171	                    : rateFigure(sheetId, person, claim);
172	            BigDecimal fixed = liveDue(figure, claim, sheets.load(sheetId), true);
173	            refuseWithoutProof(sheetId, claim, fixed);
174	            if (settings.aboveClerkLimit(sheetId, by, fixed)) {
175	                next = ClaimStatus.PENDING;
176	                event = "CLAIM_PENDING";
177	            } else {
178	                claim.setSettledDue(fixed);
179	                tail = " due=" + (fixed == null ? "n/a" : fixed.toPlainString());
180	            }
181	        }
182	        claim.setStatus(next);
183	        logStatus(by, sheetId, person, claim);
184	        Claim saved = claims.saveAndFlush(claim);
185	        audit.recordOnCommit(record(event, by, person, saved) + tail);
186	        if (next == ClaimStatus.SETTLED) {
187	            watches.notifyWatchers(by, sheetId, person, saved.getNumber());
188	        }
189	        rollup.recordChanges(by, sheetId, before);
190	        return saved;
191	    }
