343	        claim.unbind();
344	        Claim saved = claims.saveAndFlush(claim);
345	        claims.relist(saved.getId());
346	        audit.recordOnCommit(record("CLAIM_REASSIGNED", by, to, saved) + " from=" + from.getName() + " to="
347	                + to.getName());
348	        rollup.recordChanges(by, sheetId, before);
349	        return saved;
350	    }
