352	    /** An OPEN claim after a split, and the new OPEN claim split off it. */
353	    public record Split(Claim original, Claim split) {
354	    }
355	
356	    /**
357	     * Splits an amount (more than 0.00 and less than the claim's) off an OPEN claim: the claim keeps the rest and
358	     * loses any figure a statement bound it to; a new OPEN claim with the amount, the same date and note, the next
359	     * number, opened by the user, with a due-by from the terms in force on the date, and split from the original's
360	     * number, is listed as its person's newest. Refused unless the user's role may open a claim, for a claim that is
361	     * not OPEN or is deferred, for an amount out of range, and in a closed period.
362	     */
363	    @Transactional
364	    public Split split(String by, String sheetId, Long id, BigDecimal amount) {
365	        settings.refuseUnlessMay(sheetId, by, "open");
366	        Claim claim = lockedClaim(sheetId, id);
367	        if (claim.getStatus() != ClaimStatus.OPEN) {
368	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an OPEN claim can be split.");
369	        }
370	        if (claim.isDeferredOn(sheets.load(sheetId).getToday())) {
371	            throw new ResponseStatusException(HttpStatus.CONFLICT,
372	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
373	        }
374	        if (amount == null || amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
375	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
376	                    "The amount split off must be more than 0.00 and less than the claim's.");
377	        }
378	        RollupService.Snapshot before = rollup.snapshot(sheetId);
379	        Person person = person(sheetId, claim.getPersonId());
380	        claim.setAmount(claim.getAmount().subtract(scaled(amount)));
381	        claim.unbind();
382	        Claim original = claims.saveAndFlush(claim);
383	        Claim part = new Claim(sheetId, claim.getPersonId(), scaled(amount), claim.getDate(), claim.getNote());
384	        part.setRoundsOn(claim.getRoundsOn());
385	        part.setDueBy(claim.getDate().plusDays(termsFor(sheetId, person, claim.getDate())));
386	        part.setSplitFrom(claim.getNumber());
387	        part.setStatus(ClaimStatus.OPEN);
388	        number(sheetId, part);
389	        part.setOpenedBy(by);
390	        logStatus(by, sheetId, person, part);
391	        Claim added = claims.saveAndFlush(part);
392	        audit.recordOnCommit(record("CLAIM_SPLIT", by, person, original) + " into=" + added.getNumber());
393	        audit.recordOnCommit(record("CLAIM_OPENED", by, person, added));
394	        rollup.recordChanges(by, sheetId, before);
395	        return new Split(original, added);
396	    }
