398	    /**
399	     * Refuses voiding a SETTLED claim unless the user is a steward and the sheet's today is within
400	     * {@link #VOID_SETTLED_DAYS} days of the date its status log records it settled.
401	     */
402	    private void refuseVoidOfSettled(String by, String sheetId, Claim claim) {
403	        if (!settings.isSteward(sheetId, by)) {
404	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can void a settled claim.");
405	        }
406	        LocalDate settledOn = claim.settledOn();
407	        LocalDate today = sheets.load(sheetId).getToday();
408	        if (settledOn == null || today == null || today.isBefore(settledOn)
409	                || ChronoUnit.DAYS.between(settledOn, today) > VOID_SETTLED_DAYS) {
410	            throw new ResponseStatusException(HttpStatus.CONFLICT,
411	                    "A settled claim can only be voided within " + VOID_SETTLED_DAYS + " days of its settlement.");
412	        }
413	    }
