415	    /** Logs the status the claim now has: by the user, on the sheet's today, at the due it shows now. */
416	    private void logStatus(String by, String sheetId, Person person, Claim claim) {
417	        claim.logStatus(by, sheets.load(sheetId).getToday(), due(sheetId, person, claim));
418	    }
