420	    /** The pending claim, locked, for a steward to decide; refused otherwise. */
421	    private Claim pendingClaim(String by, String sheetId, Long id) {
422	        Claim claim = lockedClaim(sheetId, id);
423	        if (claim.getStatus() != ClaimStatus.PENDING) {
424	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a PENDING claim can be approved or rejected.");
425	        }
426	        if (!settings.isSteward(sheetId, by)) {
427	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can approve or reject a claim.");
428	        }
429	        return claim;
430	    }
