432	    /** The claim, locked; refused when it is dated in a closed period. */
433	    private Claim lockedClaim(String sheetId, Long id) {
434	        // the sheet is locked before the claim, in the order a period closing takes them
435	        sheets.lock(sheetId);
436	        Claim claim = claims.findWithLockByIdAndSheetId(id, sheetId)
437	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
438	        refuseInClosedPeriod(sheetId, claim.getDate());
439	        return claim;
440	    }
