442	    /**
443	     * Gives the claim being opened its number: while the sheet's period numbering from is set and its today is on or
444	     * after it, the next in the sequence of the period the claim is dated in (X for none), else the sheet's next.
445	     * The sheet is locked, so two claims opened at once never get the same one.
446	     */
447	    private void number(String sheetId, Claim claim) {
448	        Sheet sheet = sheets.load(sheetId);
449	        LocalDate from = sheet.getPeriodNumberingFrom();
450	        if (from == null || sheet.getToday().isBefore(from)) {
451	            claim.setNumber(String.valueOf(sheets.nextClaimNumber(sheetId)));
452	            return;
453	        }
454	        String sequence = periods.findFirstBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId,
455	                claim.getDate(), claim.getDate()).map(Period::getName).orElse(NO_PERIOD);
456	        Long last = claims.lastInSequence(sheetId, sequence);
457	        claim.numberIn(sequence, last == null ? 1 : last + 1);
458	    }
459	
460	    /**
461	     * The claim's rate figure: at the rate its person's grade in force on its date has in force on that date, rounded
462	     * as the sheet's policy date decides for it, with no floor; null (n/a) with none.
463	     */
464	    public BigDecimal rateFigure(String sheetId, Person person, Claim claim) {
465	        Sheet sheet = sheets.load(sheetId);
466	        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
467	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
468	                .map(pct -> dueOn(claim.getAmount(), pct, rounding)).orElse(null);
469	    }
470	
471	    /**
472	     * The figure of the claim: its settled due, else the one a statement bound it to (not while it is pending), else
473	     * its rate figure. A statement binds this figure, under the late charge and the floor.
474	     */
475	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
476	        if (claim.getSettledDue() != null) {
477	            return claim.getSettledDue();
478	        }
479	        return claim.isBound() ? claim.getStatedDue() : rateFigure(sheetId, person, claim);
480	    }
481	
482	    /**
483	     * The due the claim shows and totals: its settled due as frozen, else its live due on its figure (the late charge
484	     * only while it is open or pending).
485	     */
486	    public BigDecimal due(String sheetId, Person person, Claim claim) {
487	        BigDecimal figure = figure(sheetId, person, claim);
488	        return claim.getSettledDue() != null ? figure
489	                : liveDue(figure, claim, sheets.load(sheetId), claim.getStatus().isOpen());
490	    }
491	
492	    /**
493	     * The live due of a claim on its (unfloored) figure: the greater of the floor in force on its date and the figure
494	     * plus the late charge it has gained (when charged); a correction has neither floor nor charge. Null (n/a) for an
495	     * n/a figure.
496	     */
497	    public static BigDecimal liveDue(BigDecimal figure, Claim claim, Sheet sheet, boolean charged) {
498	        if (figure == null || claim.isCorrection()) {
499	            return figure;
500	        }
501	        BigDecimal due = charged ? withLateCharge(figure, claim, sheet) : figure;
502	        return sheet == null ? due : floored(due, sheet.floorOn(claim.getDate()));
503	    }
504	
505	    /**
506	     * The figure (null for n/a) of the claim, with a late charge added for every full 30 days it is overdue (past its
507	     * due-by) by the sheet's today: for each such boundary (its due-by plus 30, 60, 90 ... days), the sheet's late
508	     * percent in force on that boundary date of the figure, rounded like its due; a boundary whose percent is 0.00
509	     * adds nothing. A deferred claim is not overdue. The charge is never bound by a statement: it keeps following the
510	     * sheet's today and its policy date.
511	     */
512	    public static BigDecimal withLateCharge(BigDecimal figure, Claim claim, Sheet sheet) {
513	        if (figure == null || sheet == null || sheet.getToday() == null || claim.isDeferredOn(sheet.getToday())) {
514	            return figure;
515	        }
516	        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), sheet.getToday());
517	        long periods = overdue > 0 ? overdue / 30 : 0;
518	        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
519	        BigDecimal due = figure;
520	        for (long k = 1; k <= periods; k++) {
521	            BigDecimal latePct = sheet.latePctOn(claim.getDueBy().plusDays(30 * k));
522	            if (latePct.signum() != 0) {
523	                due = due.add(dueOn(figure, latePct, rounding));
524	            }
525	        }
526	        return due;
527	    }
528	
529	    /**
530	     * Refuses a change to a claim dated on the date when a closed period contains it. The sheet stays locked until
531	     * the transaction ends, so a period closing at the same moment is checked in turn.
532	     */
533	    private void refuseInClosedPeriod(String sheetId, LocalDate date) {
534	        sheets.lock(sheetId);
535	        if (periods.existsBySheetIdAndClosedTrueAndFromLessThanEqualAndToGreaterThanEqual(sheetId, date, date)) {
536	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is dated in a closed period.");
537	        }
538	    }
539	
540	    /**
541	     * The number a claim with the amount corrects: for a correction (a negative amount), the number of a settled
542	     * claim of the person, else refused; null for any other claim.
543	     */
544	    private String correctedNumber(String sheetId, Long personId, BigDecimal amount, String corrects) {
545	        if (amount.signum() >= 0) {
546	            return null;
547	        }
548	        corrects = corrects == null ? null : corrects.strip();
549	        if (corrects == null || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects,
550	                ClaimStatus.SETTLED)) {
551	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
552	                    "A negative amount must correct a settled claim of the person, named by its number.");
553	        }
554	        return corrects;
555	    }
556	
557	    /** Refuses a claim for the person dated after their retirement date; one on or before it is allowed. */
558	    private static void refuseAfterRetirement(Person person, LocalDate date) {
559	        if (person.getRetiredFrom() != null && date.isAfter(person.getRetiredFrom())) {
560	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
561	                    "That claim is dated after the person's retirement.");
562	        }
563	    }
564	
565	    private Person person(String sheetId, Long personId) {
566	        return people.findByIdAndSheetId(personId, sheetId)
567	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
568	    }
569	
570	    /**
571	     * The terms a claim of the person dated on the date has: the person's own, else those of their grade on the date,
572	     * else the sheet's on the date.
573	     */
574	    private int termsFor(String sheetId, Person person, LocalDate on) {
575	        return person.getTerms() != null ? person.getTerms()
576	                : sheets.load(sheetId).termsFor(person.gradeOn(on), on);
577	    }
578	
579	    /** The audit line about a claim; one that has a number ends with it. */
580	    private static String record(String event, String by, Person person, Claim c) {
581	        String number = c.getNumber();
582	        return event + " sheet=" + c.getSheetId() + " by=" + by + " person=" + person.getName()
583	                + " amount=" + c.getAmount().toPlainString() + " date=" + c.getDate()
584	                + (number != null ? " number=" + number : "");
585	    }
586	
587	    /**
588	     * The due on an amount at a rate: amount times rate divided by 100, rounded to two decimals the given way (a
589	     * negative amount rounds like its positive).
590	     */
591	    public static BigDecimal dueOn(BigDecimal amount, BigDecimal pct, RoundingMode rounding) {
592	        return amount.multiply(pct).movePointLeft(2).setScale(2, rounding);
593	    }
594	
595	    /** The date a claim dated on the date rounds by: that date, or for a correction the corrected claim's date. */
596	    private LocalDate roundsOn(String sheetId, String corrects, LocalDate on) {
597	        return corrects == null ? on
598	                : claims.findBySheetIdAndNumber(sheetId, corrects).map(Claim::getDate).orElse(on);
599	    }
600	
601	    /** The due raised to the floor when it is below it. */
602	    public static BigDecimal floored(BigDecimal due, BigDecimal floor) {
603	        return floor != null && due.compareTo(floor) < 0 ? floor.setScale(2) : due;
604	    }
605	
606	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
607	        return date != null ? date : sheets.load(sheetId).getToday();
608	    }
609	
610	    private static String text(BigDecimal value) {
611	        return value == null ? "n/a" : value.toPlainString();
612	    }
613	
614	    private static BigDecimal scaled(BigDecimal amount) {
615	        return amount.setScale(2, RoundingMode.UNNECESSARY);
616	    }
617	
618	    private static String noteOf(String note) {
619	        return note == null ? "" : note.strip();
620	    }
